/bin/bash -lc "python3 - <<'PY'
import os, json
from bioblend.galaxy import GalaxyInstance
url=os.environ['GALAXY_URL']
with open(os.environ['GALAXY_API_KEY_FILE']) as f: key=f.read().strip()
gi=GalaxyInstance(url=url, key=key)
t=gi.tools.show_tool('toolshed.g2.bx.psu.edu/repos/goeckslab/phykit_metrics/phykit_metrics/0.2.0+galaxy0', io_details=True)
# print input names recursively with cases
def walk(x,p=''):
    if isinstance(x, dict):
        typ=x.get('type') or x.get('model_class')
        name=x.get('name')
        if name:
            print(p+name, typ)
        for k in ['inputs','cases']:
            if k in x:
                vals=x[k]
                if k=='cases':
                    for c in vals:
                        print(p+' case='+str(c.get('value')))
                        walk(c, p+'  ')
                else:
                    for y in vals: walk(y, p+'  ')
    elif isinstance(x, list):
        for y in x: walk(y,p)
walk(t['inputs'])
PY"
